content = repo.read("logs/service.log")
lines = content.split("\n")
result = []
for i, line in enumerate(lines):
    if "ALERT" in line:
        result.append({
            "line_number": i + 1,
            "line": line,
            "prev": lines[i-1] if i > 0 else None,
            "next": lines[i+1] if i + 1 < len(lines) else None,
        })
return {"total_lines": len(lines), "matches": result}
